    dialog.id = id;
    dialog.className = `ProgrammaticModal ${opts.shape ?? 'rounded'}`;
    if (opts.contained !== false)
        dialog.classList.add('contained');
    if (opts.unstyled)
        dialog.classList.add('unstyled');
    if (opts.showScrim === false)
        dialog.classList.add('noScrim');
